cd ~/.claude/projects/-Users-<redacted>-dev-peer-review-gateway && ls -lt *.jsonl | awk '{print $6,$7,$8,$5,$9}'; echo; for f in $(ls -t *.jsonl); do echo "== $f"; python3 -I -c '
import json,sys
for l in open(sys.argv[1]):
    try: d=json.loads(l)
    except: continue
    if d.get("type")=="user" and not d.get("isMeta"):
        c=d["message"]["content"]
        if isinstance(c,list): c=" ".join(x.get("text","") for x in c if x.get("type")=="text")
        if c.strip() and not c.startswith("<"): print(d.get("timestamp"), c[:160].replace("\n"," ")); break
' "$f"; done

